{
  "cards": {
    "cover": {
      "narration": "6 days in Lisbon with the Pastel Gang, 3 of you and a city that climbs hills like it's showing off. You came, you saw, you ate the tarts.",
      "headline": "Lisbon"
    },
    "critters": {
      "narration": "You spotted 2 forms of local critters and met 1 new one along the way. Even the Lisbon pigeons seemed to nod hello, as if they knew you were tourists worth befriending."
    },
    "route": {
      "narration": "You rolled through Alfama, Belém, Sintra and Cascais, 58.9 km all told. The trams and cobbles did their best to keep you honest.",
      "line": "The 27 km leg from Belém to Sintra took 35 minutes with Uber at the wheel, 41.5 km of your trip in their capable hands."
    },
    "awards": {
      "narration": "And now, the very serious Pastel Gang awards, handed out by yours truly. No speeches longer than a tram ride, please."
    },
    "receipt": {
      "narration": "The purse strings: EUR 2,310 total, EUR 770 each, and EUR 90 under the planned EUR 2,400. Those Sintra tickets at EUR 180 were the priciest, and worth every cent of the view.",
      "line": "Everything settled in 3 days after the trip ended, no debts left to trip over on the next adventure."
    },
    "stamp": {
      "narration": "Passport stamp time: Lisbon, 4–9 Jun 2026, officially on the pass of each Pastel Gang member. Ink me impressed."
    },
    "postcard": {
      "narration": "One last look back at the trams and the tiled streets before you shuffle off home. Miss you already, you wonderful weirdos.",
      "line": "Wish you were here, but then you'd eat all the pastéis. Lisbon says olá."
    }
  },
  "awards": [
    {
      "user_id": "0199a0f2-0000-7000-8000-000000000001",
      "title": "Earliest riser",
      "line": "Rui took 2 early starts, including a 06:10 wake-up, 100% of the crew's early mornings."
    },
    {
      "user_id": "0199a0f2-0000-7000-8000-000000000002",
      "title": "Planner",
      "line": "Ines made 5 plan edits out of 6 total, 83% of the crew's changes."
    },
    {
      "user_id": "0199a0f2-0000-7000-8000-000000000003",
      "title": "Good company",
      "line": "Thank you for coming, Write a poem instead – you made every stop feel like a stanza."
    }
  ]
}
